'use client'
import { cn, Slot, useControllableSignal, useSignals } from '@cascivo/core'
import type { KeyboardEvent, ReactNode } from 'react'
import styles from './tile.module.css'

export interface TileProps {
  /** Identifies this tile within a group. */
  value: string
  /** Controlled selected state. */
  selected?: boolean
  /** Initial selected state for uncontrolled use. */
  defaultSelected?: boolean
  /** Called with this tile's value whenever it is toggled on (or off for multi). */
  onSelect?: (value: string) => void
  /**
   * Single = radio semantics (toggle on); multi = checkbox semantics (toggle on/off).
   *
   * @defaultValue `single`
   * @see the component manifest
   */
  selectable?: 'single' | 'multi'
  disabled?: boolean
  /** Optional leading icon/visual. */
  icon?: ReactNode
  /** Render as the child element instead of a div (Radix-style composition). */
  asChild?: boolean
  children?: ReactNode
  className?: string
}

/**
 * A selectable card. Renders with radio (single) or checkbox (multi) semantics and toggles via
 * click or Space/Enter. Selection is controllable; `data-selected` drives the visuals via CSS.
 */
export function Tile({
  value,
  selected,
  defaultSelected,
  onSelect,
  selectable = 'single',
  disabled,
  icon,
  asChild,
  children,
  className,
}: TileProps) {
  useSignals()
  const [isSelected, setSelected] = useControllableSignal<boolean>({
    value: selected,
    defaultValue: defaultSelected ?? false,
    onChange: () => onSelect?.(value),
  })

  const toggle = (): void => {
    if (disabled) return
    // Single behaves like a radio: selecting an already-selected tile keeps it selected.
    setSelected(selectable === 'multi' ? !isSelected.value : true)
  }

  const handleKeyDown = (e: KeyboardEvent<Element>): void => {
    if (e.key === ' ' || e.key === 'Enter') {
      e.preventDefault()
      toggle()
    }
  }

  const Comp = asChild ? Slot : 'div'

  return (
    <Comp
      role={selectable === 'multi' ? 'checkbox' : 'radio'}
      aria-checked={isSelected.value}
      aria-disabled={disabled || undefined}
      tabIndex={disabled ? -1 : 0}
      data-selected={isSelected.value || undefined}
      data-disabled={disabled || undefined}
      className={cn(styles['tile'], className)}
      onClick={toggle}
      onKeyDown={handleKeyDown}
    >
      {icon && (
        <span className={styles['icon']} aria-hidden="true">
          {icon}
        </span>
      )}
      <span className={styles['body']}>{children}</span>
    </Comp>
  )
}

@layer cascivo.component {
  .tile {
    display: flex;
    gap: var(--cascivo-space-3);
    align-items: flex-start;
    padding: var(--cascivo-space-4);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-surface);
    background: var(--cascivo-color-bg);
    color: var(--cascivo-color-text);
    cursor: pointer;
    /* `asChild` can render this styling onto a real <a>. */
    text-decoration: none;
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      translate var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);

    /* Lift on hover: the card rises and its shadow deepens, which is what makes a clickable
       surface read as clickable before the cursor lands. `translate` is composited, and the
       shadow is the only painted half. Pointer-only — a lift has no meaning under touch,
       where there is no hover state to leave. */
    @media (hover: hover) {
      &:hover:not([data-disabled]) {
        translate: 0 -2px;
        box-shadow: var(--cascivo-shadow-md);
      }
    }

    &:hover:not([data-disabled]) {
      border-color: var(--cascivo-color-border-strong);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    &[data-selected] {
      border-color: var(--cascivo-color-accent);
      background: color-mix(in oklch, var(--cascivo-color-accent) 4%, var(--cascivo-color-bg));
    }

    &[data-disabled] {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }

  .icon {
    flex: none;
    display: grid;
    place-items: center;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    color: var(--cascivo-color-text-muted);
  }

  .tile[data-selected] .icon {
    color: var(--cascivo-color-accent-text);
  }

  .body {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    font-size: var(--cascivo-text-sm);
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Tile',
  description:
    'A selectable card with radio (single) or checkbox (multi) semantics, toggled by click or keyboard',
  category: 'inputs',
  // Selection rides on role=radio/checkbox over a click handler, not a native input, so
  // nothing can be selected without JS.
  clientJs: 'required',
  states: ['default', 'selected', 'focus', 'disabled'],
  variants: ['single', 'multi'],
  sizes: [],
  props: [
    {
      name: 'value',
      description: 'Identifies this tile within a group.',
      type: 'string',
      required: true,
    },
    {
      name: 'selected',
      description: 'Controlled selected state.',
      type: 'boolean',
      required: false,
    },
    {
      name: 'defaultSelected',
      description: 'Initial selected state for uncontrolled use.',
      type: 'boolean',
      required: false,
    },
    {
      name: 'onSelect',
      description: "Called with this tile's value whenever it is toggled on (or off for multi).",
      type: '(value: string) => void',
      required: false,
    },
    {
      name: 'selectable',
      description:
        'Single = radio semantics (toggle on); multi = checkbox semantics (toggle on/off).',
      type: "'single' | 'multi'",
      required: false,
      default: 'single',
    },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
    },
    {
      name: 'icon',
      description: 'Optional leading icon/visual.',
      type: 'React.ReactNode',
      required: false,
    },
    {
      name: 'asChild',
      description:
        'When true, renders the child element as the root via Slot, merging props (polymorphic rendering).',
      type: 'boolean',
      required: false,
    },
    {
      name: 'children',
      description: 'Content rendered inside the component.',
      type: 'React.ReactNode',
      required: false,
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-accent-text',
    '--cascivo-color-bg',
    '--cascivo-color-border',
    '--cascivo-color-border-strong',
    '--cascivo-color-accent',
    '--cascivo-color-text',
    '--cascivo-color-text-muted',
    '--cascivo-radius-surface',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'radio',
    wcag: '2.2-AA',
    keyboard: ['Enter', 'Space'],
  },
  examples: [
    {
      title: 'Single-select group',
      code: `<div role="radiogroup" aria-label="Plan">
  <Tile value="starter" selected={plan === 'starter'} onSelect={setPlan}>Starter</Tile>
  <Tile value="pro" selected={plan === 'pro'} onSelect={setPlan}>Pro</Tile>
</div>`,
    },
    {
      title: 'Multi-select with icon',
      code: `<Tile value="notifications" selectable="multi" icon={<BellIcon />} defaultSelected>
  Email notifications
</Tile>`,
      description: 'Multi tiles toggle on and off like a checkbox.',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['inputs', 'tile', 'card', 'selectable', 'choice'],
  intent: {
    whenToUse: [
      'A visually rich, clickable choice card in a single- or multi-select group',
      'Plan/option pickers where each option needs an icon and supporting content',
      'A larger touch target than a plain radio or checkbox',
    ],
    whenNotToUse: [
      'A simple inline boolean — use Checkbox or Toggle',
      'A dense list of text-only options — use RadioGroup or a Select',
    ],
    antiPatterns: [
      {
        bad: '<Tile value="on">Enable</Tile> // used as a standalone on/off control',
        good: '<Tile value="on" selectable="multi">Enable</Tile> // multi allows deselect',
        why: 'Single (radio) tiles cannot be unselected by clicking; use multi for toggleable behavior',
      },
    ],
    related: [
      {
        name: 'RadioCard',
        relationship: 'alternative',
        reason:
          'RadioCard wraps a native input in a group; Tile is a standalone ARIA radio/checkbox',
      },
      {
        name: 'CheckboxCard',
        relationship: 'alternative',
        reason: 'Use CheckboxCard when native checkbox form semantics are required',
      },
    ],
    a11yRationale:
      'Exposes role="radio" (single) or role="checkbox" (multi) with aria-checked reflecting selection, is focusable, and toggles on Space/Enter. aria-disabled and a -1 tabindex remove disabled tiles from interaction.',
    flexibility: [
      {
        area: 'selectable',
        level: 'strict',
        note: 'single (radio, select-only) | multi (checkbox, toggle)',
      },
      {
        area: 'selected state',
        level: 'flexible',
        note: 'Controlled (selected/onSelect) or uncontrolled (defaultSelected)',
      },
      {
        area: 'element',
        level: 'flexible',
        note: 'asChild renders onto a custom element via Slot',
      },
    ],
  },
}
